            private StreamOptions stream = StreamOptions.DEFAULT;
            public Builder timeout(Duration value) { timeout = value; return this; }
            public Builder maxRetries(int value) { maxRetries = value; return this; }
            public Builder idempotencyKey(String value) { idempotencyKey = value; return this; }
            public Builder header(String name, String value) { headers.put(name, value); return this; }
