    /**
     * One attempt of an operation, as the client's {@code onAttempt} listener observes it:
     * the attempt number (from 1), the base URI it targeted (the client's own, or a
     * fallback after a failure), the URI it requested, the response status or the
     * transport failure when no response arrived, and the wait before the next attempt
     * (null when none follows).
     */
    public record AttemptContext(String operationId, int attempt, URI baseUri, URI requestUri, Integer statusCode,
            ApiTransportException error, Duration retryDelay) {}

    /**
     * What a lifecycle hook observes about one attempt of a call (tk omniwrap-55457rp5).
     * Immutable: no hook can change the request. {@code url} and {@code headers} carry
     * every credential as "[redacted]": Authorization, Proxy-Authorization, Cookie, each
     * API-key header and query parameter, and any configured credential value.
     * {@code attempt} counts from 1, {@code elapsed} runs from the start of the call,
     * {@code statusCode} is null until the server answered, {@code error} is the failure
     * of the attempt (onRetry) or of the call (onError), and {@code retryDelay} is the wait
     * before the next attempt on onRetry.
     */
    public record HookContext(String operationId, String method, String url, Map<String, List<String>> headers,
            int attempt, Duration elapsed, Integer statusCode, Throwable error, Duration retryDelay) {}

    /**
     * Request lifecycle hooks. Every attempt starts with {@code beforeRequest} and ends with
     * exactly one of {@code onRetry} (another attempt follows), {@code afterResponse} (the
     * success the call returns) or {@code onError} (the failure the call completes with).
     * Implement only the callbacks you need; a hook's own exception ends the call with it.
     */
    public interface RequestHooks {
        /** Before each attempt is sent. */
        default void beforeRequest(HookContext context) {}
        /** The attempt received the success response the call returns. */
        default void afterResponse(HookContext context) {}
        /** The attempt failed and another one follows after {@code retryDelay}. */
        default void onRetry(HookContext context) {}
        /** The call failed; {@code statusCode} is set when the server answered. */
        default void onError(HookContext context) {}
    }

