        /** The longest accepted {@code reconnectDelay}, also the cap on a server {@code retry}. */
        public static final Duration MAX_RECONNECT_DELAY = Duration.ofSeconds(60);
        /** The largest accepted {@code maxLineLength}. */
        public static final int MAX_LINE_LENGTH = 100_000_000;
