        /** How many times a server-sent-event stream may resume. */
        public int maxReconnects() { return maxReconnects; }
        /** The wait before a resumption until the server sends {@code retry}. */
        public Duration reconnectDelay() { return reconnectDelay; }
        /** The {@code Last-Event-ID} seeded on the first request, or null. */
        public String lastEventId() { return lastEventId; }
        /** The hook observing each resumption, or null. */
        public Consumer<ReconnectContext> onReconnect() { return onReconnect; }
        /** The largest server-sent event or NDJSON line, in bytes. */
        public int maxLineLength() { return maxLineLength; }
        public static Builder builder() { return new Builder(); }
