            private int maxReconnects;
            private Duration reconnectDelay = Duration.ofSeconds(1);
            private String lastEventId;
            private Consumer<ReconnectContext> onReconnect;
            private int maxLineLength = 1_000_000;
            private Builder() {}
            public Builder maxReconnects(int value) { maxReconnects = value; return this; }
            public Builder reconnectDelay(Duration value) { reconnectDelay = value; return this; }
            public Builder lastEventId(String value) { lastEventId = value; return this; }
